export function renderTodos(todos) {
  const items = todos.map((t) => (t.done ? `<li class="done">${t.text}</li>` : `<li>${t.text}</li>`)).join('')
  const left = todos.filter((t) => !t.done).length
  return `<ul>${items}</ul><p>${left} left</p>`
}

tests.code:
import { expect, test } from 'vitest'
import { renderTodos } from './renderTodos'

test('renders items and the count', () => {
  expect(renderTodos([{ text: 'a', done: false }, { text: 'b', done: false }])).toBe('<ul><li>a</li><li>b</li></ul><p>2 left</p>')
})

test('done items get a class and are not counted', () => {
  expect(renderTodos([{ text: 'a', done: true }, { text: 'b', done: false }])).toBe('<ul><li class="done">a</li><li>b</li></ul><p>1 left</p>')
})

test('same input gives the same output', () => {
  const t = [{ text: 'x', done: false }]
  expect(renderTodos(t)).toBe(renderTodos(t))
  expect(renderTodos([])).toBe('<ul></ul><p>0 left</p>')
})

