export function UserList({ users }) {
  if (users.length === 0) return <p>No users</p>
  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>{u.name}{u.admin && ' (admin)'}</li>
      ))}
    </ul>
  )
}

tests.code:
