import { expect, test } from 'vitest'
import { UserList } from './UserList'

test('lists users and marks admins', () => {
  render(<UserList users={[{ id: 1, name: 'A', admin: true }, { id: 2, name: 'B', admin: false }]} />)
  const items = screen.getAllByRole('listitem').map((li) => li.textContent)
  expect(items).toEqual(['A (admin)', 'B'])
})

test('shows a message when empty', () => {
  render(<UserList users={[]} />)
  expect(screen.getByText('No users')).toBeTruthy()
  expect(screen.queryByRole('list')).toBeNull()
})

test('escapes names', () => {
  render(<UserList users={[{ id: 1, name: '<b>x</b>' }]} />)
  expect(screen.getByRole('listitem').textContent).toBe('<b>x</b>')
})

