export function Avatar({ name, size = 40, onClick }) {
  const parts = name.trim().split(/\s+/)
  const initials = (parts[0][0] + (parts.length > 1 ? parts.at(-1)[0] : '')).toUpperCase()
  return (
    <button aria-label={name} style={{ width: size, height: size }} onClick={() => onClick?.(name)}>
      {initials}
    </button>
  )
}

